import math

def is_pretty(m, n, alpha, k):
    if m <= 0 or n <= 0:
        return False
    val = m * math.ceil(n * alpha) - n * math.floor(m * alpha)
    return val == k

def count_cool_pairs(k, alpha, limit):
    cool_pairs = []
    # Since we don't know the range of m, n, we need a way to bound them.
    # However, let's try a range first.
    for m in range(1, limit):
        for n in range(1, limit):
            if is_pretty(m, n, alpha, k):
                # (m, n) is pretty
                # check if (m-n, n) is pretty or (m, n-m) is pretty
                is_cool = True
                if m - n > 0:
                    if is_pretty(m - n, n, alpha, k):
                        is_cool = False
                if is_cool and n - m > 0:
                    if is_pretty(m, n - m, alpha, k):
                        is_cool = False

                if is_cool:
                    cool_pairs.append((m, n))
    return cool_pairs

# Test with small k
alpha = math.sqrt(2)
for k in range(1, 11):
    pairs = count_cool_pairs(k, alpha, 100)
    print(f"k={k}, cool_pairs={pairs}, count={len(pairs)}")

